class LRUCache {
  constructor(capacity) {
    this.capacity = capacity
    this.map  = new Map()   // key → node  (O(1) lookup)
    this.head = { key: null, prev: null, next: null }  // most recent
    this.tail = { key: null, prev: null, next: null }  // least recent
    this.head.next = this.tail
    this.tail.prev = this.head
  }

  get(key) {
    if (!this.map.has(key)) return -1  // miss
    const node = this.map.get(key)
    this.moveToHead(node)               // mark as recently used
    return node.value
  }

  put(key, value) {
    if (this.map.has(key)) {
      const node = this.map.get(key)
      node.value = value
      this.moveToHead(node)
    } else {
      const node = { key, value, prev: null, next: null }
      this.map.set(key, node)
      this.addToHead(node)
      if (this.map.size > this.capacity) {
        const lru = this.removeTail()  // evict least recently used
        this.map.delete(lru.key)
      }
    }
  }
  // moveToHead, addToHead, removeTail — standard linked list ops
}

