class LFUCache {
  constructor(capacity) {
    this.capacity = capacity
    this.minFreq   = 0
    this.keyMap    = new Map()  // key → { value, freq }
    this.freqMap   = new Map()  // freq → Set of keys
  }

  get(key) {
    if (!this.keyMap.has(key)) return -1
    this._increment(key)         // bump frequency count
    return this.keyMap.get(key).value
  }

  put(key, value) {
    if (this.capacity <= 0) return
    if (this.keyMap.has(key)) {
      this.keyMap.get(key).value = value
      this._increment(key)
    } else {
      if (this.keyMap.size >= this.capacity) {
        // Evict the least frequent key
        const lfuSet = this.freqMap.get(this.minFreq)
        const evict  = lfuSet.values().next().value
        lfuSet.delete(evict)
        this.keyMap.delete(evict)
      }
      this.keyMap.set(key, { value, freq: 1 })
      if (!this.freqMap.has(1)) this.freqMap.set(1, new Set())
      this.freqMap.get(1).add(key)
      this.minFreq = 1             // new entry always starts at freq 1
    }
  }

  _increment(key) {
    const { value, freq } = this.keyMap.get(key)
    this.freqMap.get(freq).delete(key)
    if (freq === this.minFreq && this.freqMap.get(freq).size === 0)
      this.minFreq++
    const newFreq = freq + 1
    if (!this.freqMap.has(newFreq)) this.freqMap.set(newFreq, new Set())
    this.freqMap.get(newFreq).add(key)
    this.keyMap.set(key, { value, freq: newFreq })
  }
}
// All operations O(1) — frequency tracking with no sorting needed

