class FIFOCache {
  constructor(capacity) {
    this.capacity = capacity
    this.cache    = new Map()   // Map preserves insertion order
  }

  get(key) {
    return this.cache.has(key) ? this.cache.get(key) : -1
    // No order update on access — pure insertion order
  }

  put(key, value) {
    if (this.cache.has(key)) {
      this.cache.delete(key)  // remove and re-insert to update value
    } else if (this.cache.size >= this.capacity) {
      // Evict the first inserted key
      const firstKey = this.cache.keys().next().value
      this.cache.delete(firstKey)
    }
    this.cache.set(key, value)
  }
}
// JavaScript Map naturally preserves insertion order
// .keys().next().value = oldest inserted key = O(1)

